Here's a simple, dependency-free cache (in-memory `Map` plus `localStorage`, with a TTL). It keeps the app under 2.5 MB.

**cache.js**
```js
const TTL_MS = 60 * 60 * 1000; // 60 min
const STORAGE_KEY = 'weatherCache';
const memory = new Map();

function loadStore() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
  } catch {
    return {}; // corrupted JSON
  }
}

function isFresh(entry) {
  return entry && Date.now() - entry.timestamp < TTL_MS;
}

export function getCached(key) {
  const entry = memory.get(key) || loadStore()[key];
  if (!isFresh(entry)) {
    memory.delete(key);
    return null;
  }
  memory.set(key, entry);
  return entry.data;
}

export function setCached(key, data) {
  const entry = { data, timestamp: Date.now() };
  memory.set(key, entry);

  const store = loadStore();
  Object.keys(store).forEach((k) => {
    if (!isFresh(store[k])) delete store[k]; // prune expired
  });
  store[key] = entry;

  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(store));
  } catch {
    // storage full: keep the in-memory copy only
  }
}
```

**fetchWeatherData() using it**
```js
import { getCached, setCached } from './cache.js';
import { WEATHER_URL, API_KEY } from './config.js';

export async function fetchWeatherData(city) {
  const key = city.trim().toLowerCase();
  const cached = getCached(key);
  if (cached) return cached;

  const url = `${WEATHER_URL}?q=${encodeURIComponent(city)}&units=metric&appid=${API_KEY}`;
  const response = await fetch(url);

  if (!response.ok) {
    if (response.status === 401) throw new Error('Invalid API key');
    if (response.status === 404) throw new Error('City not found');
    throw new Error(`HTTP error ${response.status}`); // 429 goes to the apiClient.js backoff
  }

  const data = await response.json();
  setCached(key, data); // cache successful responses only
  return data;
}
```

